<?php
declare(strict_types=1);require_once __DIR__.'/config/db.php';require_once __DIR__.'/admin_auth.php';require_once __DIR__.'/skin_journey_common.php';
$origin=$_SERVER['HTTP_ORIGIN']??'';if(preg_match('/^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/',$origin)===1){header('Access-Control-Allow-Origin: '.$origin);header('Vary: Origin');}header('Content-Type: application/json; charset=utf-8');header('Access-Control-Allow-Methods: GET, POST, OPTIONS');header('Access-Control-Allow-Headers: Content-Type, Authorization, X-Admin-Token');header('X-Content-Type-Options: nosniff');if(($_SERVER['REQUEST_METHOD']??'GET')==='OPTIONS'){http_response_code(204);exit;}requireAdminAuth();
function journeyJson(int $status,array $payload):never{http_response_code($status);echo json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
try{$pdo=getDatabaseConnection();ensureSkinJourneySchema($pdo);$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET')journeyJson(200,array_merge(['success'=>true],readSkinJourneyState($pdo)));if($method!=='POST')journeyJson(405,['success'=>false,'message'=>'Method not allowed.']);$in=json_decode(file_get_contents('php://input')?:'',true);$in=is_array($in)?$in:[];if(!($in['confirmed']??false))journeyJson(422,['success'=>false,'message'=>'Explicit human confirmation is required.']);$action=journeyText($in['action']??'',50);$reason=journeyText($in['reason']??'',1000);$actor=journeyText($in['actor']??'Admin',190);if(strlen($reason)<12)journeyJson(422,['success'=>false,'message'=>'A clear audit reason is required.']);
 if($action==='create_journey_draft'){$reference=journeyText($in['customer_reference']??'',190);$concern=journeyText($in['concern']??'',190);$consent=journeyText($in['consent_reference']??'',190);$owner=journeyText($in['owner']??'',190);$baseline=max(1,min(5,(int)($in['baseline_score']??0)));if($reference===''||$concern===''||$consent===''||$owner==='')journeyJson(422,['success'=>false,'message'=>'Customer reference, concern, participation consent reference and owner are required.']);$hash=hash('sha256',strtolower($reference));$mask='Customer • '.strtoupper(substr($hash,0,6));$pdo->beginTransaction();$save=$pdo->prepare("INSERT INTO skin_journeys(journey_key,customer_reference_hash,customer_mask,concern,secondary_goal,routine_reference,owner,participation_consent_reference,status,baseline_score)VALUES(:key,:hash,:mask,:concern,:secondary,:routine,:owner,:consent,'draft',:baseline)");$save->execute([':key'=>bin2hex(random_bytes(16)),':hash'=>$hash,':mask'=>$mask,':concern'=>$concern,':secondary'=>journeyText($in['secondary_goal']??'',190),':routine'=>journeyText($in['routine_reference']??'',190),':owner'=>$owner,':consent'=>$consent,':baseline'=>$baseline]);$id=(int)$pdo->lastInsertId();$event=$pdo->prepare("INSERT INTO skin_journey_events(journey_id,action_name,after_json,reason,actor)VALUES(:id,'create_draft',:after,:reason,:actor)");$event->execute([':id'=>$id,':after'=>json_encode(['status'=>'draft','concern'=>$concern],JSON_UNESCAPED_SLASHES),':reason'=>$reason,':actor'=>$actor]);$pdo->commit();journeyJson(200,array_merge(['success'=>true,'message'=>'Private journey draft saved; no diagnosis, routine change or publication occurred.'],readSkinJourneyState($pdo)));}
 if($action==='record_checkin'){$id=max(0,(int)($in['journey_id']??0));$wording=journeyText($in['customer_wording']??'',3000);$comfort=journeyText($in['comfort']??'',40);$allowed=['comfortable','mostly_comfortable','uncomfortable','reaction_reported'];if($id===0||$wording===''||!in_array($comfort,$allowed,true))journeyJson(422,['success'=>false,'message'=>'Journey, preserved customer wording and comfort are required.']);$find=$pdo->prepare('SELECT * FROM skin_journeys WHERE id=:id LIMIT 1 FOR UPDATE');$pdo->beginTransaction();$find->execute([':id'=>$id]);$before=$find->fetch(PDO::FETCH_ASSOC);if(!$before){$pdo->rollBack();journeyJson(404,['success'=>false,'message'=>'Journey not found.']);}if($before['participation_consent_status']!=='active'){$pdo->rollBack();journeyJson(422,['success'=>false,'message'=>'Active participation consent is required.']);}$score=max(1,min(5,(int)($in['progress_score']??0)));$adherence=max(0,min(100,(int)($in['adherence_percent']??0)));$check=$pdo->prepare('INSERT INTO skin_journey_checkins(journey_id,progress_score,comfort,adherence_percent,customer_wording,source_channel,routine_snapshot,reported_at,recorded_by)VALUES(:id,:score,:comfort,:adherence,:wording,:source,:routine,NOW(),:actor)');$check->execute([':id'=>$id,':score'=>$score,':comfort'=>$comfort,':adherence'=>$adherence,':wording'=>$wording,':source'=>journeyText($in['source_channel']??'Admin',80),':routine'=>journeyText($in['routine_snapshot']??'',500),':actor'=>$actor]);$status=in_array($comfort,['uncomfortable','reaction_reported'],true)?'needs_review':'active';$pdo->prepare('UPDATE skin_journeys SET status=:status,next_review_at=DATE_ADD(CURDATE(),INTERVAL 14 DAY) WHERE id=:id')->execute([':status'=>$status,':id'=>$id]);$event=$pdo->prepare("INSERT INTO skin_journey_events(journey_id,action_name,before_json,after_json,reason,actor)VALUES(:id,'record_checkin',:before,:after,:reason,:actor)");$event->execute([':id'=>$id,':before'=>json_encode(['status'=>$before['status']]),':after'=>json_encode(['status'=>$status,'comfort'=>$comfort,'score'=>$score]),':reason'=>$reason,':actor'=>$actor]);$pdo->commit();journeyJson(200,array_merge(['success'=>true,'message'=>'Customer-reported check-in recorded; comfort alerts require human review.'],readSkinJourneyState($pdo)));}journeyJson(400,['success'=>false,'message'=>'Unknown action.']);
}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('Skin journey error: '.$e->getMessage());journeyJson(500,['success'=>false,'message'=>'Skin journey data could not be loaded.']);}
